import { isNil, uniq } from 'lodash-es';
import React from 'react';

import { WithChildren } from '../../../core/types/with-children.js';
import {
  getDatapointIsGap,
  getThresholdValue,
} from '../../core/functions/apply-gap-policy.js';
import { safeGet } from '../../core/functions/safe-get.js';
import {
  TimeseriesDatapoint,
  TimeseriesUnit,
} from '../../core/types/timeseries.js';
import {
  getRelativeValue,
  groupValueByTimestamp,
} from '../components/displays/shared/functions/apply-value-representation.js';
import {
  CumulativePoint,
  getCumulativeValue,
} from '../components/displays/shared/functions/datapoint-stacking.js';
import { isBandDataPoint } from '../components/displays/shared/functions/get-timeseries-type.js';
import { TimeseriesDataPointAllTypes } from '../components/displays/shared/types.js';
import { TimeseriesFilteredDataContext } from '../context/TimeseriesFilteredData.context.js';
import { useFilteredSeriesIdsState } from '../hooks/store/selectors.js';
import { useMinMaxXAxis } from '../hooks/useMinMaxXAxis.js';
import { useTimeseriesData } from '../hooks/useTimeseriesData.js';
import { useXAxisConfig } from '../hooks/useXAxisConfig.js';
import {
  TimeseriesBandDataPoint,
  TimeseriesBandSlotProps,
} from '../types/timeseries-band.js';
import {
  ChartVariantInternal,
  DatapointsMap,
  TimeseriesPerVariant,
  TimeseriesVariantSlotProps,
  ValueRepresentationPerVariant,
  WeakMapDatapoints,
  WeakMapSeries,
} from '../types/timeseries.js';
import { detectMisalignedDatapoints } from '../utils/detectInconsistencies.js';
import { isStacked } from '../utils/is-stacked.js';
import {
  getDatapointTime,
  mergeTimeseriesFromVariants,
} from '../utils/timeseries.js';

function getSanitizedValueRepresentation(
  data: TimeseriesPerVariant,
  valueRepPerVariant: ValueRepresentationPerVariant,
) {
  const { area } = data;

  if (area && area.length > 0) {
    const valueRepresentation = valueRepPerVariant.get('area') ?? 'absolute';
    const misalignedDatapoints = detectMisalignedDatapoints(area);
    const isMisaligned =
      misalignedDatapoints && valueRepresentation === 'relative';

    valueRepPerVariant.set(
      'area',
      isMisaligned ? 'absolute' : valueRepresentation,
    );
  }

  return valueRepPerVariant;
}

function getRelativeConf(
  series: TimeseriesBandSlotProps[] | TimeseriesVariantSlotProps[],
  variant: ChartVariantInternal,
  valueRepPerVariant: ValueRepresentationPerVariant,
  units: TimeseriesUnit[],
) {
  const relative =
    valueRepPerVariant.get(variant) === 'relative' &&
    units.length < 2 &&
    variant !== 'band';

  const groupedValues = relative
    ? groupValueByTimestamp(series as TimeseriesVariantSlotProps[])
    : undefined;

  return groupedValues;
}

function getDatapointValue(
  datapoint: TimeseriesDatapoint | TimeseriesBandDataPoint,
  variant: ChartVariantInternal,
  relativeGroupedValues?: Map<number, number>,
) {
  if (variant === 'band') {
    const { y0, y1 } = datapoint as TimeseriesBandDataPoint;

    return { y0, y1 };
  }

  const { value, start, end, center } = datapoint as TimeseriesDatapoint;

  if (relativeGroupedValues) {
    const total =
      relativeGroupedValues.get(getDatapointTime(start, end, center)) ?? 0;
    const allowNegative = variant === 'bar';
    const relativeValue = getRelativeValue(value, total, allowNegative);

    return { absolute: value, value: relativeValue };
  }

  return { value };
}

export function useBuildFilteredMetadata(
  data: TimeseriesPerVariant,
  valueRepPerVariant: ValueRepresentationPerVariant,
  seriesMap: WeakMapSeries,
  units: TimeseriesUnit[],
) {
  const xConfig = useXAxisConfig();
  const { min, max } = useMinMaxXAxis();

  const datapointsMap: WeakMapDatapoints = new WeakMap();

  const sanitizedValueRepPerVariant = getSanitizedValueRepresentation(
    data,
    valueRepPerVariant,
  );

  const filteredTimeseries: TimeseriesPerVariant = { ...data };
  const filteredUnits: TimeseriesUnit[] = [];
  const originalFilteredUnits: TimeseriesUnit[] = [];

  for (const variant of data.shapePriority) {
    const cumulativeStackedPoints = new Map<string, CumulativePoint>();
    const lastSignStacked = new Map<string, number>();

    const variantSeries = data[variant];

    const relativeGroupedValues = getRelativeConf(
      variantSeries,
      variant,
      sanitizedValueRepPerVariant,
      units,
    );

    const newSeries: (TimeseriesVariantSlotProps | TimeseriesBandSlotProps)[] =
      [];

    for (let i = 0; i < variantSeries.length; i++) {
      const series = variantSeries[i];
      const seriesMetadata = safeGet(seriesMap, series);
      const { id, color, gapPolicy, pointsDisplay } = seriesMetadata;
      const unit = relativeGroupedValues ? 'percent' : series.unit;
      const originalUnit = relativeGroupedValues ? series.unit : undefined;

      const metadata = {
        id,
        color,
        unit,
        originalUnit,
        gapPolicy,
        pointsDisplay,
      };

      filteredUnits.push(unit);
      originalFilteredUnits.push(originalUnit);

      seriesMap.set(series, metadata);

      const thresholdGap = getThresholdValue(gapPolicy);
      const newDatapoints: (TimeseriesDatapoint | TimeseriesBandDataPoint)[] =
        [];

      // FYI: DO NOT use SPREAD OPERATOR, this will significantly impact the performance of this code.
      for (let j = 0; j < series.datapoints.length; j++) {
        const datapoint = series.datapoints[j];

        // Validate if the data point is within the min/max range
        if (xConfig && (xConfig.min || xConfig.max)) {
          const dataPointTimestamp = getDatapointTime(
            datapoint.start,
            datapoint.end,
            (datapoint as TimeseriesDatapoint).center,
          );
          const dataPointOutOfBounds =
            dataPointTimestamp < +min || dataPointTimestamp > +max;
          if (dataPointOutOfBounds) {
            continue;
          }
        }

        const nextDatapoint = series.datapoints[j + 1];

        const { absolute, value, y0, y1 } = getDatapointValue(
          datapoint,
          variant,
          relativeGroupedValues,
        );

        const isBandPointUndefined =
          isBandDataPoint(datapoint) && (isNil(y0) || isNil(y1));
        const isPointUndefined = !isBandDataPoint(datapoint) && isNil(value);

        // FYI: this is the undefined validation, do not use a point if its undefined.
        if (isBandPointUndefined || isPointUndefined) {
          continue;
        }

        const isGap = getDatapointIsGap(
          datapoint,
          nextDatapoint,
          gapPolicy,
          thresholdGap,
        );

        let stackedSign = value ?? 0;
        const key =
          datapoint.start.getTime().toString() + datapoint.end?.getTime();

        if (value === 0) {
          const prevSign = lastSignStacked.get(key) ?? 0;

          stackedSign = prevSign;
        }

        const cumulativeStack = isStacked(variant)
          ? getCumulativeValue(
              cumulativeStackedPoints,
              datapoint as TimeseriesDatapoint,
              unit,
              id,
              value,
              stackedSign,
            )
          : undefined;

        const datapointMetadata: DatapointsMap = {
          start: datapoint.start,
          end: datapoint.end,
          center: (datapoint as TimeseriesDatapoint).center,
          seriesId: id,
          color,
          unit,
          isGap: false,
          absoluteValue: absolute,
          value,
          variant,
          y0,
          y1,
          cumulativeValue: cumulativeStack?.cumulativeValue ?? 0,
          seriesName: series.name,
          originalUnit: originalUnit,
          userData: series.userData as Record<string, any>, // eslint-disable-line @typescript-eslint/no-explicit-any
        };

        if (isStacked(variant) && cumulativeStack) {
          cumulativeStackedPoints.set(cumulativeStack.key, {
            seriesId: id,
            datapointsCumulative: cumulativeStack.datapointsCumulative,
            baseCumulative: cumulativeStack.baseCumulative,
          });

          lastSignStacked.set(key, stackedSign);
        }

        datapointsMap.set(datapoint, datapointMetadata);
        newDatapoints.push(datapoint);

        if (isGap) {
          const metadataGappedDatapoint = {
            ...datapointMetadata,
            isGap: true,
            value: Infinity,
          };
          const gappedDatapoint = {
            start: datapoint.end ?? datapoint.start,
            end: nextDatapoint.start,
            isGap: true,
            value: Infinity,
          };

          datapointsMap.set(gappedDatapoint, metadataGappedDatapoint);
          newDatapoints.push(gappedDatapoint);
        }
      }

      const { datapoints, ...spreadSeries } = series;
      const newSingleSeries = { ...spreadSeries, datapoints: newDatapoints } as
        | TimeseriesBandSlotProps
        | TimeseriesVariantSlotProps;

      newSeries.push(newSingleSeries);
      seriesMap.set(newSingleSeries, metadata);
    }

    filteredTimeseries[variant] = newSeries as TimeseriesVariantSlotProps[] &
      TimeseriesBandSlotProps[];
  }

  return {
    seriesMap: seriesMap,
    datapointsMap,
    filteredUnits: uniq(filteredUnits),
    filteredTimeseries,
    originalFilteredUnits: uniq(originalFilteredUnits),
  };
}

export const TimeseriesFilteredDataProvider = ({ children }: WithChildren) => {
  const {
    dataPerVariant,
    seriesMap: initialSeriesMap,
    valueRepPerVariant,
    units,
  } = useTimeseriesData();
  const filteredSeriesIds = useFilteredSeriesIdsState();

  const hasId = (
    series: TimeseriesVariantSlotProps | TimeseriesBandSlotProps,
  ) => filteredSeriesIds.has(safeGet(initialSeriesMap, series).id);

  const filteredTimeseriesPerVariant =
    filteredSeriesIds.size > 0
      ? {
          ...dataPerVariant,
          line: dataPerVariant['line'].filter(hasId),
          bar: dataPerVariant['bar'].filter(hasId),
          area: dataPerVariant['area'].filter(hasId),
          band: dataPerVariant['band'].filter(hasId),
        }
      : dataPerVariant;

  const {
    seriesMap,
    datapointsMap,
    filteredUnits,
    filteredTimeseries,
    originalFilteredUnits,
  } = useBuildFilteredMetadata(
    filteredTimeseriesPerVariant,
    valueRepPerVariant,
    initialSeriesMap,
    units ?? [],
  );

  const data = mergeTimeseriesFromVariants(filteredTimeseries);
  const allDatapoints = data.flatMap(
    (series) => series.datapoints as TimeseriesDataPointAllTypes[],
  );

  return (
    <TimeseriesFilteredDataContext.Provider
      value={{
        data,
        dataPerVariant: filteredTimeseries,
        seriesMap,
        datapointsMap,
        units: filteredUnits,
        originalUnits: originalFilteredUnits,
        allDatapoints,
      }}
    >
      {children}
    </TimeseriesFilteredDataContext.Provider>
  );
};
